using GenApp.Domain.Customers;

namespace GenApp.Application.Customers;

public interface ICustomerRepository
{
    // LGACDB01: INSERT INTO CUSTOMER (lgacdb01.cbl:251-273). The number is generated by the database on SaveChanges.
    void Add(Customer customer);

    // LGACDB02: INSERT INTO CUSTOMER_SECURE (lgacdb02.cbl:143-182).
    void AddSecurity(CustomerSecure security);

    // LGICDB01: SELECT ... FROM CUSTOMER WHERE CUSTOMERNUMBER = ... (lgicdb01.cbl:169-190). Null when there is no row.
    Task<Customer?> FindAsync(int customerNumber, CancellationToken cancellationToken = default);

    // LGUCDB01: UPDATE CUSTOMER SET <all nine columns> WHERE CUSTOMERNUMBER = ... (lgucdb01.cbl:152-169).
    // Runs at once and returns the number of rows updated; 0 means there is no such customer.
    Task<int> UpdateAsync(Customer customer, CancellationToken cancellationToken = default);
}
